# =============================================================================
# 1-Click Installer: Save Selection as Markdown (TeX & Mermaid) for MS Edge
# Built by Minagy Labs (v1.0)
# =============================================================================
# Run this script in PowerShell (Right-click -> Run with PowerShell) to unpack
# the Microsoft Edge extension to $HOME\EdgeMarkdownSaver and open Edge.

$TargetDir = Join-Path $HOME "EdgeMarkdownSaver"
New-Item -ItemType Directory -Force -Path $TargetDir | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $TargetDir "icons") | Out-Null

$Files = @{
    "manifest.json" = ""
    "content.js" = ""
    "background.js" = ""
    "icons/icon128.png" = ""
    "icons/icon16.png" = "iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAoklEQVR4nKVTsRGAIAxMPHvtdAW1cxwHdBw7cQXpZAKtiLlIBPQbcgn/94EEgaFq+hMS4KxBHyMndvOSwodtGkmo9MluXqgQA7+LVdOfOWQpQg6OfaVi3Q5qTrZZhNQ5MYagQI7IQ8BblXG2g1QXZShZtwMc+0ongD4jqgNpX/vm1xYkvAgXoxa0B4s5KZw1uE1j8h4A3FPorMHfy4S88GWdL9KOTUFPa41dAAAAAElFTkSuQmCC"
    "icons/icon32.png" = ""
    "icons/icon48.png" = ""
}

foreach ($entry in $Files.GetEnumerator()) {
    $filePath = Join-Path $TargetDir ($entry.Key -replace '/', '\')
    $bytes = [System.Convert]::FromBase64String($entry.Value)
    [System.IO.File]::WriteAllBytes($filePath, $bytes)
}

Write-Host "Extension files extracted to: $TargetDir" -ForegroundColor Cyan
Write-Host "1. In Microsoft Edge, enable Developer mode (toggle on the left/bottom)." -ForegroundColor Yellow
Write-Host "2. Click Load unpacked and select: $TargetDir" -ForegroundColor Green
Start-Process "msedge.exe" "edge://extensions/"
explorer.exe $TargetDir
